### trier_tableau
```javascript
function trier_tableau(arr) {
  if (arr.length <= 1) return arr;

  const quickSort = (array) => {
    if (array.length <= 1) return array;

    const pivot = array[Math.floor(array.length / 2)];
    const left = [];
    const middle = [];
    const right = [];

    for (let x of array) {
      if (x < pivot) {
        left.push(x);
      } else if (x > pivot) {
        right.push(x);
      } else {
        middle.push(x);
      }
    }

    return [...quickSort(left), ...middle, ...quickSort(right)];
  };

  // We return a new array to avoid mutating the original if desired, 
  // but standard sort behavior usually returns the sorted result.
  return quickSort([...arr]);
}
```

