function medianeDeuxTries(a, b) {
  // Ensure 'a' is the shorter array to optimize binary search complexity
  if (a.length > b.length) return medianeDeuxTries(b, a);

  let x = a.length;
  let y = b.length;
  let low = 0;
  let high = x;

  while (low <= high) {
    let partitionX = Math.floor((low + high) / 2);
    let partitionY = Math.floor((x + y + 1) / 2) - partitionX;

    let maxLeftX = (partitionX === 0) ? -Infinity : a[partitionX - 1];
    let minRightX = (partitionX === x) ? Infinity : a[partitionX];

    let maxLeftY = (partitionY === 0) ? -Infinity : b[partitionY - 1];
    let minRightY = (partitionY === y) ? Infinity : b[partitionY];

    if (maxLeftX <= minRightY && maxLeftY <= minRightX) {
      // We have partitioned the arrays correctly
      if ((x + y) % 2 === 0) {
        return (Math.max(maxLeftX, maxLeftY) + Math.min(minRightX, minRightY)) / 2;
      } else {
        return Math.max(maxLeftX, maxLeftY);
      }
    } else if (maxLeftX > minRightY) {
      high = partitionX - 1;
    } else {
      low = partitionX + 1;
    }
  }
  return 0.0;
}
