function plusLongueSousSuiteCroissante(tab) {
  if (tab.length === 0) return 0;

  // tails[i] will store the smallest tail of all increasing subsequences of length i+1
  const tails = [];

  for (let x of tab) {
    let i = 0;
    let j = tails.length;

    // Binary search to find the insertion point for x
    while (i < j) {
      let mid = Math.floor((i + j) / 2);
      if (tails[mid] < x) {
        i = mid + 1;
      } else {
        j = mid;
      }
    }

    if (i === tails.length) {
      tails.push(x);
    } else {
      tails[i] = x;
    }
  }

  return tails.length;
}
